// Playground problems (one object per line). Run `npm run verify:problems` after editing:
// it checks every solution against its tests in both JavaScript and Python.
import type { CodingProblem } from "./problems";

export const strmathProblems: CodingProblem[] = [
  {"id": "repeated-dna-sequences", "title": "Repeated DNA Sequences", "level": "Medium", "topic": "string-hashing", "pattern": "Rolling hash over a fixed window", "statement": "Return every 10-letter substring that occurs more than once in the DNA string `s` (letters A, C, G, T), in any order.", "examples": [{"input": "s = \"AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT\"", "output": "[\"AAAAACCCCC\",\"CCCCCAAAAA\"]"}, {"input": "s = \"AAAAAAAAAAAAA\"", "output": "[\"AAAAAAAAAA\"]"}], "fn": {"js": "findRepeatedDnaSequences", "py": "find_repeated_dna_sequences"}, "starter": {"js": "function findRepeatedDnaSequences(s) {\n  // your code here\n}\n", "py": "def find_repeated_dna_sequences(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function findRepeatedDnaSequences(s) {\n  const seen = new Set(), out = new Set();\n  for (let i = 0; i + 10 <= s.length; i++) {\n    const sub = s.slice(i, i + 10);   // a set of substrings: simpler, O(10·n)\n    if (seen.has(sub)) out.add(sub);\n    seen.add(sub);\n  }\n  return [...out];\n}\n", "py": "def find_repeated_dna_sequences(s):\n    code = {\"A\": 0, \"C\": 1, \"G\": 2, \"T\": 3}\n    seen, out = set(), set()\n    h, mask = 0, (1 << 20) - 1          # 10 letters × 2 bits = 20-bit rolling hash\n    for i, ch in enumerate(s):\n        h = ((h << 2) | code[ch]) & mask\n        if i >= 9:\n            if h in seen:\n                out.add(s[i - 9:i + 1])\n            seen.add(h)\n    return list(out)\n"}, "tests": [{"args": ["AAAAACCCCCAAAAACCCCCCAAAAAGGGTTT"], "expected": ["CCCCCAAAAA", "AAAAACCCCC"]}, {"args": ["AAAAAAAAAAAAA"], "expected": ["AAAAAAAAAA"]}, {"args": ["ACGT"], "expected": []}, {"args": ["ACGTACGTACGTACGTACGT"], "expected": ["GTACGTACGT", "ACGTACGTAC", "TACGTACGTA", "CGTACGTACG"]}, {"args": [""], "expected": []}], "compare": "unordered", "hints": ["A set of all 10-letter substrings works in O(10·n).", "A rolling hash (2 bits per letter, 20 bits per window) updates in O(1) per step."], "complexity": "O(n) time, O(n) space"},
  {"id": "longest-duplicate-substring", "title": "Longest Duplicate Substring (length)", "level": "Hard", "topic": "string-hashing", "pattern": "Binary search on length + Rabin-Karp", "statement": "Return the length of the longest substring of `s` that occurs at least twice (occurrences may overlap). Return 0 if none.", "examples": [{"input": "s = \"banana\"", "output": "3", "explain": "\"ana\" occurs twice (overlapping)."}, {"input": "s = \"abcd\"", "output": "0"}], "fn": {"js": "longestDupSubstringLength", "py": "longest_dup_substring_length"}, "starter": {"js": "function longestDupSubstringLength(s) {\n  // your code here\n}\n", "py": "def longest_dup_substring_length(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function longestDupSubstringLength(s) {\n  // Binary search on L; a Set of substrings keeps the JS version simple (O(n·L) per check).\n  const hasDup = (L) => {\n    const seen = new Set();\n    for (let i = 0; i + L <= s.length; i++) {\n      const sub = s.slice(i, i + L);\n      if (seen.has(sub)) return true;\n      seen.add(sub);\n    }\n    return false;\n  };\n  let lo = 0, hi = Math.max(0, s.length - 1);\n  while (lo < hi) {\n    const mid = (lo + hi + 1) >> 1;\n    if (hasDup(mid)) lo = mid; else hi = mid - 1;\n  }\n  return lo;\n}\n", "py": "def longest_dup_substring_length(s):\n    n, MOD, B = len(s), (1 << 61) - 1, 131\n    def has_dup(L):\n        if L == 0:\n            return True\n        h, power = 0, pow(B, L, MOD)\n        seen = {}\n        for i, ch in enumerate(s):\n            h = (h * B + ord(ch)) % MOD\n            if i >= L:\n                h = (h - ord(s[i - L]) * power) % MOD\n            if i >= L - 1:\n                start = i - L + 1\n                for j in seen.get(h, []):          # verify to rule out collisions\n                    if s[j:j + L] == s[start:start + L]:\n                        return True\n                seen.setdefault(h, []).append(start)\n        return False\n    lo, hi = 0, n - 1                    # answer is monotone in L\n    while lo < hi:\n        mid = (lo + hi + 1) // 2\n        if has_dup(mid):\n            lo = mid\n        else:\n            hi = mid - 1\n    return lo\n"}, "tests": [{"args": ["banana"], "expected": 3}, {"args": ["abcd"], "expected": 0}, {"args": ["a"], "expected": 0}, {"args": ["aa"], "expected": 1}, {"args": ["aaaaa"], "expected": 4}, {"args": ["mississippi"], "expected": 4}, {"args": ["abcabcabcxyzabcabcabc"], "expected": 9}], "hints": ["If a duplicate of length L exists, one of length L − 1 does too: binary search on L.", "Check a length in O(n) with a rolling hash of every window (verify on hash matches to be safe)."], "complexity": "O(n log n) expected time"},
  {"id": "repeated-substring-pattern", "title": "Repeated Substring Pattern", "level": "Easy", "topic": "kmp", "pattern": "Prefix function / doubling trick", "statement": "Return `true` if `s` can be built by repeating one of its substrings (at least twice).", "examples": [{"input": "s = \"abab\"", "output": "true"}, {"input": "s = \"aba\"", "output": "false"}, {"input": "s = \"abcabcabcabc\"", "output": "true"}], "fn": {"js": "repeatedSubstringPattern", "py": "repeated_substring_pattern"}, "starter": {"js": "function repeatedSubstringPattern(s) {\n  // your code here\n}\n", "py": "def repeated_substring_pattern(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function repeatedSubstringPattern(s) {\n  // Doubling trick: s is periodic iff it appears in (s + s) with the first and last characters removed.\n  return (s + s).slice(1, -1).includes(s);\n}\n", "py": "def repeated_substring_pattern(s):\n    n = len(s)\n    pi = [0] * n                         # KMP prefix function\n    for i in range(1, n):\n        k = pi[i - 1]\n        while k and s[i] != s[k]:\n            k = pi[k - 1]\n        if s[i] == s[k]:\n            k += 1\n        pi[i] = k\n    p = n - pi[-1] if n else 0           # smallest period\n    return n > 0 and pi[-1] > 0 and n % p == 0\n"}, "tests": [{"args": ["abab"], "expected": true}, {"args": ["aba"], "expected": false}, {"args": ["abcabcabcabc"], "expected": true}, {"args": ["a"], "expected": false}, {"args": ["aa"], "expected": true}, {"args": ["abac"], "expected": false}, {"args": ["xyzxyzxy"], "expected": false}], "hints": ["Trick: s is a repetition iff s occurs inside (s + s) without its first and last characters.", "With KMP: the smallest period is n − π[n − 1]; check it divides n and the period is shorter than n."], "complexity": "O(n) time"},
  {"id": "shortest-palindrome", "title": "Shortest Palindrome", "level": "Hard", "topic": "kmp", "pattern": "Longest palindromic prefix via prefix function", "statement": "Add characters only at the front of `s` to make the shortest possible palindrome. Return it.", "examples": [{"input": "s = \"aacecaaa\"", "output": "\"aaacecaaa\""}, {"input": "s = \"abcd\"", "output": "\"dcbabcd\""}], "fn": {"js": "shortestPalindrome", "py": "shortest_palindrome"}, "starter": {"js": "function shortestPalindrome(s) {\n  // your code here\n}\n", "py": "def shortest_palindrome(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function shortestPalindrome(s) {\n  const t = s + \"#\" + [...s].reverse().join(\"\"), pi = new Array(t.length).fill(0);\n  for (let i = 1; i < t.length; i++) {\n    let k = pi[i - 1];\n    while (k && t[i] !== t[k]) k = pi[k - 1];\n    if (t[i] === t[k]) k++;\n    pi[i] = k;\n  }\n  const keep = pi[t.length - 1];\n  return [...s.slice(keep)].reverse().join(\"\") + s;\n}\n", "py": "def shortest_palindrome(s):\n    t = s + \"#\" + s[::-1]                # π of the combined string = longest palindromic prefix\n    pi = [0] * len(t)\n    for i in range(1, len(t)):\n        k = pi[i - 1]\n        while k and t[i] != t[k]:\n            k = pi[k - 1]\n        if t[i] == t[k]:\n            k += 1\n        pi[i] = k\n    keep = pi[-1] if t else 0\n    return s[keep:][::-1] + s\n"}, "tests": [{"args": ["aacecaaa"], "expected": "aaacecaaa"}, {"args": ["abcd"], "expected": "dcbabcd"}, {"args": [""], "expected": ""}, {"args": ["a"], "expected": "a"}, {"args": ["aba"], "expected": "aba"}, {"args": ["abb"], "expected": "bbabb"}, {"args": ["aabba"], "expected": "abbaabba"}], "hints": ["You only need to find the longest prefix of s that is a palindrome; reverse the rest and put it in front.", "That prefix length is the prefix function value at the end of s + '#' + reverse(s)."], "complexity": "O(n) time and space"},
  {"id": "z-array", "title": "Compute the Z-Array", "level": "Medium", "topic": "z-function", "pattern": "Z-box [l, r)", "statement": "Return the Z-array of `s`: `z[i]` is the length of the longest common prefix of s and s[i:], with z[0] = 0 by convention.", "examples": [{"input": "s = \"aabxaab\"", "output": "[0,1,0,0,3,1,0]"}, {"input": "s = \"aaaaa\"", "output": "[0,4,3,2,1]"}], "fn": {"js": "zFunction", "py": "z_function"}, "starter": {"js": "function zFunction(s) {\n  // your code here\n}\n", "py": "def z_function(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function zFunction(s) {\n  const n = s.length, z = new Array(n).fill(0);\n  let l = 0, r = 0;\n  for (let i = 1; i < n; i++) {\n    if (i < r) z[i] = Math.min(r - i, z[i - l]);\n    while (i + z[i] < n && s[z[i]] === s[i + z[i]]) z[i]++;\n    if (i + z[i] > r) { l = i; r = i + z[i]; }\n  }\n  return z;\n}\n", "py": "def z_function(s):\n    n = len(s)\n    z = [0] * n\n    l = r = 0                                # s[l:r] matches a prefix of s\n    for i in range(1, n):\n        if i < r:\n            z[i] = min(r - i, z[i - l])      # reuse what we know inside the box\n        while i + z[i] < n and s[z[i]] == s[i + z[i]]:\n            z[i] += 1\n        if i + z[i] > r:\n            l, r = i, i + z[i]\n    return z\n"}, "tests": [{"args": ["aabxaab"], "expected": [0, 1, 0, 0, 3, 1, 0]}, {"args": ["aaaaa"], "expected": [0, 4, 3, 2, 1]}, {"args": [""], "expected": []}, {"args": ["a"], "expected": [0]}, {"args": ["abacaba"], "expected": [0, 0, 1, 0, 3, 0, 1]}, {"args": ["abcabcab"], "expected": [0, 0, 0, 5, 0, 0, 2, 0]}], "hints": ["The naive version compares from scratch at every i: O(n²).", "Keep the rightmost window [l, r) that matches a prefix. Inside it, z[i] starts at min(r − i, z[i − l]); extend only past r."], "complexity": "O(n) time"},
  {"id": "longest-palindromic-substring", "title": "Longest Palindromic Substring", "level": "Medium", "topic": "manacher", "pattern": "Expand around center (Manacher for O(n))", "statement": "Return the longest palindromic substring of `s`. If several have the maximum length, return the one that starts first.", "examples": [{"input": "s = \"babad\"", "output": "\"bab\""}, {"input": "s = \"cbbd\"", "output": "\"bb\""}], "fn": {"js": "longestPalindrome", "py": "longest_palindrome"}, "starter": {"js": "function longestPalindrome(s) {\n  // your code here\n}\n", "py": "def longest_palindrome(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function longestPalindrome(s) {\n  // Manacher's algorithm on the transformed string ^#a#b#...#$\n  const t = \"^#\" + s.split(\"\").join(\"#\") + \"#$\", p = new Array(t.length).fill(0);\n  let c = 0, r = 0;\n  for (let i = 1; i < t.length - 1; i++) {\n    if (i < r) p[i] = Math.min(r - i, p[2 * c - i]);\n    while (t[i + p[i] + 1] === t[i - p[i] - 1]) p[i]++;\n    if (i + p[i] > r) { c = i; r = i + p[i]; }\n  }\n  let bestLen = 0, bestStart = 0;\n  for (let i = 1; i < t.length - 1; i++) {\n    const start = (i - p[i]) >> 1;      // start index in s\n    if (p[i] > bestLen || (p[i] === bestLen && start < bestStart)) { bestLen = p[i]; bestStart = start; }\n  }\n  return s.slice(bestStart, bestStart + bestLen);\n}\n", "py": "def longest_palindrome(s):\n    best_l, best_len = 0, 0\n    for center in range(2 * len(s) - 1):\n        l, r = center // 2, center // 2 + center % 2\n        while l >= 0 and r < len(s) and s[l] == s[r]:\n            l -= 1; r += 1\n        length = r - l - 1\n        if length > best_len or (length == best_len and l + 1 < best_l):\n            best_l, best_len = l + 1, length\n    return s[best_l:best_l + best_len]\n"}, "tests": [{"args": ["babad"], "expected": "bab"}, {"args": ["cbbd"], "expected": "bb"}, {"args": ["a"], "expected": "a"}, {"args": [""], "expected": ""}, {"args": ["forgeeksskeegfor"], "expected": "geeksskeeg"}, {"args": ["abacdfgdcaba"], "expected": "aba"}, {"args": ["aaaa"], "expected": "aaaa"}], "hints": ["Every palindrome has a center: n single characters and n − 1 gaps. Expand from each: O(n²).", "Manacher reuses mirror information inside the rightmost palindrome to get O(n)."], "complexity": "O(n²) expand-around-center, O(n) Manacher"},
  {"id": "suffix-array-construction", "title": "Build a Suffix Array", "level": "Medium", "topic": "suffix-array", "pattern": "Prefix doubling", "statement": "Return the suffix array of `s`: the starting indices of all suffixes, sorted lexicographically.", "examples": [{"input": "s = \"banana\"", "output": "[5,3,1,0,4,2]"}, {"input": "s = \"abc\"", "output": "[0,1,2]"}], "fn": {"js": "suffixArray", "py": "suffix_array"}, "starter": {"js": "function suffixArray(s) {\n  // your code here\n}\n", "py": "def suffix_array(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function suffixArray(s) {\n  // Direct sort of suffixes: O(n² log n), fine for short strings and easy to trust.\n  return [...Array(s.length).keys()].sort((a, b) => { const x = s.slice(a), y = s.slice(b); return x < y ? -1 : x > y ? 1 : 0; });\n}\n", "py": "def suffix_array(s):\n    n = len(s)\n    rank = [ord(c) for c in s]\n    sa, k = list(range(n)), 1\n    while True:\n        key = lambda i: (rank[i], rank[i + k] if i + k < n else -1)\n        sa.sort(key=key)                       # sort by the first 2k characters\n        new = [0] * n\n        for j in range(1, n):\n            new[sa[j]] = new[sa[j - 1]] + (key(sa[j]) != key(sa[j - 1]))\n        rank = new\n        if n == 0 or rank[sa[-1]] == n - 1:    # all ranks distinct: done\n            return sa\n        k *= 2\n"}, "tests": [{"args": ["banana"], "expected": [5, 3, 1, 0, 4, 2]}, {"args": ["abc"], "expected": [0, 1, 2]}, {"args": [""], "expected": []}, {"args": ["a"], "expected": [0]}, {"args": ["aaaa"], "expected": [3, 2, 1, 0]}, {"args": ["mississippi"], "expected": [10, 7, 4, 1, 0, 9, 8, 6, 3, 5, 2]}, {"args": ["abracadabra"], "expected": [10, 7, 0, 3, 5, 8, 1, 4, 6, 9, 2]}], "hints": ["Sorting suffixes directly costs O(n² log n) because comparisons are O(n).", "Prefix doubling: sort by the first k characters using the ranks of the first k/2 and the next k/2. log n rounds."], "complexity": "O(n log² n) with comparison sorting"},
  {"id": "count-distinct-substrings", "title": "Count Distinct Substrings", "level": "Medium", "topic": "suffix-array", "pattern": "n(n+1)/2 − Σ LCP", "statement": "Return the number of distinct non-empty substrings of `s`.", "examples": [{"input": "s = \"abab\"", "output": "7", "explain": "a, b, ab, ba, aba, bab, abab"}, {"input": "s = \"aaa\"", "output": "3"}], "fn": {"js": "countDistinctSubstrings", "py": "count_distinct_substrings"}, "starter": {"js": "function countDistinctSubstrings(s) {\n  // your code here\n}\n", "py": "def count_distinct_substrings(s):\n    # your code here\n    pass\n"}, "solution": {"js": "function countDistinctSubstrings(s) {\n  // Insert every substring into a trie: the number of trie nodes = distinct substrings. O(n²).\n  const root = {};\n  let count = 0;\n  for (let i = 0; i < s.length; i++) {\n    let node = root;\n    for (let j = i; j < s.length; j++) {\n      if (!node[s[j]]) { node[s[j]] = {}; count++; }\n      node = node[s[j]];\n    }\n  }\n  return count;\n}\n", "py": "def count_distinct_substrings(s):\n    n = len(s)\n    sa = sorted(range(n), key=lambda i: s[i:])            # simple suffix array\n    rank = [0] * n\n    for i, p in enumerate(sa):\n        rank[p] = i\n    lcp, h = [0] * n, 0                                   # Kasai: lcp[i] = LCP(sa[i-1], sa[i])\n    for i in range(n):\n        if rank[i] > 0:\n            j = sa[rank[i] - 1]\n            while i + h < n and j + h < n and s[i + h] == s[j + h]:\n                h += 1\n            lcp[rank[i]] = h\n            if h:\n                h -= 1\n        else:\n            h = 0\n    return n * (n + 1) // 2 - sum(lcp)    # each suffix adds its length minus the shared prefix\n"}, "tests": [{"args": ["abab"], "expected": 7}, {"args": ["aaa"], "expected": 3}, {"args": [""], "expected": 0}, {"args": ["a"], "expected": 1}, {"args": ["abc"], "expected": 6}, {"args": ["banana"], "expected": 15}, {"args": ["mississippi"], "expected": 53}], "hints": ["Every substring is a prefix of some suffix.", "In suffix-array order, suffix i contributes (its length − LCP with the previous suffix) new substrings."], "complexity": "O(n log n) with a fast suffix array + Kasai (O(n²) trie alternative)"},
  {"id": "multi-pattern-search", "title": "Count Occurrences of Many Patterns", "level": "Hard", "topic": "aho-corasick", "pattern": "Aho-Corasick automaton", "statement": "Given a `text` and a list of distinct `patterns`, return an array where entry i is the number of (possibly overlapping) occurrences of `patterns[i]` in text.", "examples": [{"input": "text = \"ahishers\", patterns = [\"he\",\"she\",\"hers\",\"his\"]", "output": "[1,1,1,1]"}, {"input": "text = \"aaaa\", patterns = [\"a\",\"aa\",\"aaa\"]", "output": "[4,3,2]"}], "fn": {"js": "countOccurrences", "py": "count_occurrences"}, "starter": {"js": "function countOccurrences(text, patterns) {\n  // your code here\n}\n", "py": "def count_occurrences(text, patterns):\n    # your code here\n    pass\n"}, "solution": {"js": "function countOccurrences(text, patterns) {\n  // Baseline: KMP-free sliding check per pattern. O(|text| · Σ|p|) — fine for small inputs.\n  return patterns.map((p) => {\n    let c = 0;\n    for (let i = 0; i + p.length <= text.length; i++) if (text.startsWith(p, i)) c++;\n    return c;\n  });\n}\n", "py": "from collections import deque\n\ndef count_occurrences(text, patterns):\n    goto, fail, out = [{}], [0], [[]]\n    for idx, p in enumerate(patterns):                 # 1. build the trie\n        node = 0\n        for ch in p:\n            if ch not in goto[node]:\n                goto.append({}); fail.append(0); out.append([])\n                goto[node][ch] = len(goto) - 1\n            node = goto[node][ch]\n        out[node].append(idx)\n    q = deque(goto[0].values())                        # 2. BFS for failure links\n    while q:\n        u = q.popleft()\n        for ch, v in goto[u].items():\n            f = fail[u]\n            while f and ch not in goto[f]:\n                f = fail[f]\n            fail[v] = goto[f][ch] if ch in goto[f] and goto[f][ch] != v else 0\n            out[v] += out[fail[v]]                     # inherit matches ending here\n            q.append(v)\n    counts, node = [0] * len(patterns), 0\n    for ch in text:                                     # 3. scan the text once\n        while node and ch not in goto[node]:\n            node = fail[node]\n        node = goto[node].get(ch, 0)\n        for idx in out[node]:\n            counts[idx] += 1\n    return counts\n"}, "tests": [{"args": ["ahishers", ["he", "she", "hers", "his"]], "expected": [1, 1, 1, 1]}, {"args": ["aaaa", ["a", "aa", "aaa"]], "expected": [4, 3, 2]}, {"args": ["abc", ["d"]], "expected": [0]}, {"args": ["abababab", ["ab", "bab", "abab", "b"]], "expected": [4, 3, 3, 4]}, {"args": ["mississippi", ["ss", "issi", "i", "ppi", "sis"]], "expected": [2, 2, 4, 1, 1]}], "hints": ["Running KMP once per pattern costs O(k · |text|).", "Aho-Corasick: a trie of patterns plus failure links (KMP on a trie). One pass over the text finds every match."], "complexity": "O(|text| + Σ|patterns| + matches)"},
  {"id": "add-digits", "title": "Add Digits", "level": "Easy", "topic": "number-basics", "pattern": "Digital root (mod 9)", "statement": "Repeatedly add all digits of the non-negative integer `num` until one digit remains, and return it. Can you do it in O(1)?", "examples": [{"input": "num = 38", "output": "2", "explain": "3 + 8 = 11, 1 + 1 = 2"}, {"input": "num = 0", "output": "0"}], "fn": {"js": "addDigits", "py": "add_digits"}, "starter": {"js": "function addDigits(num) {\n  // your code here\n}\n", "py": "def add_digits(num):\n    # your code here\n    pass\n"}, "solution": {"js": "function addDigits(num) {\n  while (num >= 10) {\n    let s = 0;\n    for (; num > 0; num = Math.floor(num / 10)) s += num % 10;\n    num = s;\n  }\n  return num;\n}\n", "py": "def add_digits(num):\n    # A number ≡ its digit sum (mod 9), so the digital root is 1 + (num - 1) % 9.\n    return 0 if num == 0 else 1 + (num - 1) % 9\n"}, "tests": [{"args": [38], "expected": 2}, {"args": [0], "expected": 0}, {"args": [9], "expected": 9}, {"args": [10], "expected": 1}, {"args": [999999999], "expected": 9}, {"args": [123456789], "expected": 9}], "hints": ["The simulation peels digits with % 10 and // 10.", "10 ≡ 1 (mod 9), so every number is congruent to its digit sum mod 9."], "complexity": "O(1) with the formula"},
  {"id": "excel-column-number", "title": "Excel Sheet Column Number", "level": "Easy", "topic": "number-basics", "pattern": "Base-26 without a zero digit", "statement": "Convert an Excel column title (A, B, …, Z, AA, AB, …) to its column number (A = 1).", "examples": [{"input": "column_title = \"A\"", "output": "1"}, {"input": "column_title = \"AB\"", "output": "28"}, {"input": "column_title = \"ZY\"", "output": "701"}], "fn": {"js": "titleToNumber", "py": "title_to_number"}, "starter": {"js": "function titleToNumber(columnTitle) {\n  // your code here\n}\n", "py": "def title_to_number(column_title):\n    # your code here\n    pass\n"}, "solution": {"js": "function titleToNumber(columnTitle) {\n  let n = 0;\n  for (const ch of columnTitle) n = n * 26 + (ch.charCodeAt(0) - 64);\n  return n;\n}\n", "py": "def title_to_number(column_title):\n    n = 0\n    for ch in column_title:\n        n = n * 26 + (ord(ch) - ord(\"A\") + 1)\n    return n\n"}, "tests": [{"args": ["A"], "expected": 1}, {"args": ["AB"], "expected": 28}, {"args": ["ZY"], "expected": 701}, {"args": ["Z"], "expected": 26}, {"args": ["AA"], "expected": 27}, {"args": ["FXSHRXW"], "expected": 2147483647}], "hints": ["It's base 26 with digits 1..26 instead of 0..25.", "Horner's rule: n = n · 26 + digit."], "complexity": "O(length) time"},
  {"id": "convert-to-base", "title": "Convert to Base k", "level": "Easy", "topic": "number-basics", "pattern": "Repeated division", "statement": "Return the representation of integer `num` in base `k` (2 ≤ k ≤ 10) as a string, with a leading `-` for negatives.", "examples": [{"input": "num = 100, k = 7", "output": "\"202\""}, {"input": "num = -7, k = 7", "output": "\"-10\""}, {"input": "num = 10, k = 2", "output": "\"1010\""}], "fn": {"js": "convertToBase", "py": "convert_to_base"}, "starter": {"js": "function convertToBase(num, k) {\n  // your code here\n}\n", "py": "def convert_to_base(num, k):\n    # your code here\n    pass\n"}, "solution": {"js": "function convertToBase(num, k) {\n  if (num === 0) return \"0\";\n  const neg = num < 0;\n  num = Math.abs(num);\n  let out = \"\";\n  while (num > 0) { out = String(num % k) + out; num = Math.floor(num / k); }\n  return (neg ? \"-\" : \"\") + out;\n}\n", "py": "def convert_to_base(num, k):\n    if num == 0:\n        return \"0\"\n    neg, num = num < 0, abs(num)\n    digits = []\n    while num:\n        num, d = divmod(num, k)\n        digits.append(str(d))\n    return (\"-\" if neg else \"\") + \"\".join(reversed(digits))\n"}, "tests": [{"args": [100, 7], "expected": "202"}, {"args": [-7, 7], "expected": "-10"}, {"args": [10, 2], "expected": "1010"}, {"args": [0, 3], "expected": "0"}, {"args": [1, 2], "expected": "1"}, {"args": [-255, 2], "expected": "-11111111"}, {"args": [999999, 9], "expected": "1783660"}], "hints": ["The last digit is num % k; then divide by k and repeat.", "Handle the sign separately: % and integer division on negatives behave differently across languages."], "complexity": "O(log_k |num|) time"},
  {"id": "gcd-of-strings", "title": "Greatest Common Divisor of Strings", "level": "Easy", "topic": "gcd-lcm", "pattern": "Commutation test + gcd of lengths", "statement": "String t divides s if s is t repeated some number of times. Return the largest string that divides both `str1` and `str2` (or `\"\"`).", "examples": [{"input": "str1 = \"ABCABC\", str2 = \"ABC\"", "output": "\"ABC\""}, {"input": "str1 = \"ABABAB\", str2 = \"ABAB\"", "output": "\"AB\""}, {"input": "str1 = \"LEET\", str2 = \"CODE\"", "output": "\"\""}], "fn": {"js": "gcdOfStrings", "py": "gcd_of_strings"}, "starter": {"js": "function gcdOfStrings(str1, str2) {\n  // your code here\n}\n", "py": "def gcd_of_strings(str1, str2):\n    # your code here\n    pass\n"}, "solution": {"js": "function gcdOfStrings(str1, str2) {\n  if (str1 + str2 !== str2 + str1) return \"\";\n  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));\n  return str1.slice(0, gcd(str1.length, str2.length));\n}\n", "py": "from math import gcd\n\ndef gcd_of_strings(str1, str2):\n    if str1 + str2 != str2 + str1:\n        return \"\"                     # no common \"unit\" string exists\n    return str1[:gcd(len(str1), len(str2))]\n"}, "tests": [{"args": ["ABCABC", "ABC"], "expected": "ABC"}, {"args": ["ABABAB", "ABAB"], "expected": "AB"}, {"args": ["LEET", "CODE"], "expected": ""}, {"args": ["A", "A"], "expected": "A"}, {"args": ["AAAA", "AA"], "expected": "AA"}, {"args": ["ABAB", "BABA"], "expected": ""}, {"args": ["XYXYXY", "XYXY"], "expected": "XY"}], "hints": ["If both are built from the same block, str1 + str2 == str2 + str1.", "Then the largest block has length gcd(len1, len2)."], "complexity": "O(n + m) time"},
  {"id": "water-and-jug", "title": "Water and Jug Problem", "level": "Medium", "topic": "gcd-lcm", "pattern": "Bézout's identity", "statement": "With jugs of capacities `x` and `y` litres (fill, empty, pour between jugs), can you end up with exactly `target` litres in total across both jugs?", "examples": [{"input": "x = 3, y = 5, target = 4", "output": "true"}, {"input": "x = 2, y = 6, target = 5", "output": "false"}, {"input": "x = 1, y = 2, target = 3", "output": "true"}], "fn": {"js": "canMeasureWater", "py": "can_measure_water"}, "starter": {"js": "function canMeasureWater(x, y, target) {\n  // your code here\n}\n", "py": "def can_measure_water(x, y, target):\n    # your code here\n    pass\n"}, "solution": {"js": "function canMeasureWater(x, y, target) {\n  // BFS over states (a, b): slower but a direct simulation, handy to convince yourself.\n  if (target > x + y) return false;\n  const seen = new Set(), q = [[0, 0]];\n  seen.add(\"0,0\");\n  for (let i = 0; i < q.length; i++) {\n    const [a, b] = q[i];\n    if (a + b === target) return true;\n    const pourAB = Math.min(a, y - b), pourBA = Math.min(b, x - a);\n    for (const [na, nb] of [[x, b], [a, y], [0, b], [a, 0], [a - pourAB, b + pourAB], [a + pourBA, b - pourBA]]) {\n      const k = na + \",\" + nb;\n      if (!seen.has(k)) { seen.add(k); q.push([na, nb]); }\n    }\n  }\n  return false;\n}\n", "py": "from math import gcd\n\ndef can_measure_water(x, y, target):\n    # Reachable amounts are exactly the multiples of gcd(x, y) up to x + y (Bézout).\n    if target > x + y:\n        return False\n    return target % gcd(x, y) == 0\n"}, "tests": [{"args": [3, 5, 4], "expected": true}, {"args": [2, 6, 5], "expected": false}, {"args": [1, 2, 3], "expected": true}, {"args": [4, 6, 8], "expected": true}, {"args": [6, 9, 1], "expected": false}, {"args": [13, 11, 1], "expected": true}, {"args": [1, 1, 0], "expected": true}], "hints": ["Simulating states (a, b) with BFS works for small capacities.", "Bézout: every reachable total is a multiple of gcd(x, y), and every such multiple up to x + y is reachable."], "complexity": "O(log min(x, y)) time"},
  {"id": "prime-factorization", "title": "Prime Factorization", "level": "Easy", "topic": "primes", "pattern": "Trial division up to √n", "statement": "Return the prime factors of `n` (2 ≤ n ≤ 10¹²) in non-decreasing order, with multiplicity.", "examples": [{"input": "n = 12", "output": "[2,2,3]"}, {"input": "n = 97", "output": "[97]"}], "fn": {"js": "primeFactors", "py": "prime_factors"}, "starter": {"js": "function primeFactors(n) {\n  // your code here\n}\n", "py": "def prime_factors(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function primeFactors(n) {\n  const out = [];\n  for (let d = 2; d * d <= n; d += d === 2 ? 1 : 2)\n    while (n % d === 0) { out.push(d); n /= d; }\n  if (n > 1) out.push(n);\n  return out;\n}\n", "py": "def prime_factors(n):\n    out, d = [], 2\n    while d * d <= n:\n        while n % d == 0:\n            out.append(d)\n            n //= d\n        d += 1 if d == 2 else 2           # after 2, only odd candidates\n    if n > 1:\n        out.append(n)                      # what's left is prime\n    return out\n"}, "tests": [{"args": [12], "expected": [2, 2, 3]}, {"args": [97], "expected": [97]}, {"args": [2], "expected": [2]}, {"args": [360], "expected": [2, 2, 2, 3, 3, 5]}, {"args": [1000000007], "expected": [1000000007]}, {"args": [999999999989], "expected": [999999999989]}, {"args": [600851475143], "expected": [71, 839, 1471, 6857]}], "hints": ["Divide out each factor as many times as it goes, starting from 2.", "You only need to test d with d² ≤ n: whatever remains above 1 is a prime."], "complexity": "O(√n) time"},
  {"id": "ugly-number-ii", "title": "Ugly Number II", "level": "Medium", "topic": "primes", "pattern": "Three pointers merging multiples", "statement": "Ugly numbers have only 2, 3 and 5 as prime factors (1 counts). Return the n-th ugly number.", "examples": [{"input": "n = 10", "output": "12", "explain": "1, 2, 3, 4, 5, 6, 8, 9, 10, 12"}, {"input": "n = 1", "output": "1"}], "fn": {"js": "nthUglyNumber", "py": "nth_ugly_number"}, "starter": {"js": "function nthUglyNumber(n) {\n  // your code here\n}\n", "py": "def nth_ugly_number(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function nthUglyNumber(n) {\n  const ugly = [1];\n  let i2 = 0, i3 = 0, i5 = 0;\n  while (ugly.length < n) {\n    const next = Math.min(ugly[i2] * 2, ugly[i3] * 3, ugly[i5] * 5);\n    ugly.push(next);\n    if (next === ugly[i2] * 2) i2++;\n    if (next === ugly[i3] * 3) i3++;\n    if (next === ugly[i5] * 5) i5++;\n  }\n  return ugly[n - 1];\n}\n", "py": "def nth_ugly_number(n):\n    ugly = [1]\n    i2 = i3 = i5 = 0\n    while len(ugly) < n:\n        nxt = min(ugly[i2] * 2, ugly[i3] * 3, ugly[i5] * 5)\n        ugly.append(nxt)\n        if nxt == ugly[i2] * 2: i2 += 1     # advance every pointer that produced nxt\n        if nxt == ugly[i3] * 3: i3 += 1     # (this also skips duplicates like 6)\n        if nxt == ugly[i5] * 5: i5 += 1\n    return ugly[-1]\n"}, "tests": [{"args": [10], "expected": 12}, {"args": [1], "expected": 1}, {"args": [7], "expected": 8}, {"args": [11], "expected": 15}, {"args": [150], "expected": 5832}, {"args": [1690], "expected": 2123366400}], "hints": ["Every ugly number is a smaller ugly number times 2, 3 or 5.", "Merge the three sorted streams (ugly × 2, × 3, × 5) with three pointers."], "complexity": "O(n) time and space"},
  {"id": "count-good-numbers", "title": "Count Good Numbers", "level": "Medium", "topic": "modular-arithmetic", "pattern": "Fast power mod 1e9+7", "statement": "A digit string is good if digits at even indices are even (0,2,4,6,8) and digits at odd indices are prime (2,3,5,7). Return the number of good strings of length `n` modulo 10⁹ + 7 (n can be up to 10¹⁵).", "examples": [{"input": "n = 1", "output": "5"}, {"input": "n = 4", "output": "400"}, {"input": "n = 50", "output": "564908303"}], "fn": {"js": "countGoodNumbers", "py": "count_good_numbers"}, "starter": {"js": "function countGoodNumbers(n) {\n  // your code here\n}\n", "py": "def count_good_numbers(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function countGoodNumbers(n) {\n  const MOD = 1000000007n;\n  const pow = (b, e) => { let r = 1n; b %= MOD; while (e > 0n) { if (e & 1n) r = (r * b) % MOD; b = (b * b) % MOD; e >>= 1n; } return r; };\n  const N = BigInt(n);\n  return Number((pow(5n, (N + 1n) / 2n) * pow(4n, N / 2n)) % MOD);   // BigInt: products exceed 2^53\n}\n", "py": "def count_good_numbers(n):\n    MOD = 10**9 + 7\n    even_slots, odd_slots = (n + 1) // 2, n // 2\n    return pow(5, even_slots, MOD) * pow(4, odd_slots, MOD) % MOD\n"}, "tests": [{"args": [1], "expected": 5}, {"args": [4], "expected": 400}, {"args": [50], "expected": 564908303}, {"args": [2], "expected": 20}, {"args": [3], "expected": 100}, {"args": [1000000000000000], "expected": 711414395}, {"args": [806166225460393], "expected": 643535977}], "hints": ["The answer is 5^⌈n/2⌉ · 4^⌊n/2⌋.", "n is huge: use fast exponentiation, reducing mod 10⁹ + 7 after every multiplication (BigInt in JS)."], "complexity": "O(log n) time"},
  {"id": "modular-inverse", "title": "Modular Inverse", "level": "Medium", "topic": "modular-arithmetic", "pattern": "Extended Euclid", "statement": "Return the smallest positive x with (a · x) mod m = 1, or −1 if it doesn't exist (when gcd(a, m) ≠ 1). Here 1 ≤ a, m ≤ 10⁹ and m ≥ 2.", "examples": [{"input": "a = 3, m = 11", "output": "4", "explain": "3 · 4 = 12 ≡ 1 (mod 11)"}, {"input": "a = 10, m = 17", "output": "12"}, {"input": "a = 6, m = 9", "output": "-1"}], "fn": {"js": "modInverse", "py": "mod_inverse"}, "starter": {"js": "function modInverse(a, m) {\n  // your code here\n}\n", "py": "def mod_inverse(a, m):\n    # your code here\n    pass\n"}, "solution": {"js": "function modInverse(a, m) {\n  let r0 = a % m, r1 = m, x0 = 1, x1 = 0;\n  while (r1 !== 0) {\n    const q = Math.floor(r0 / r1);\n    [r0, r1] = [r1, r0 - q * r1];\n    [x0, x1] = [x1, x0 - q * x1];\n  }\n  return r0 === 1 ? ((x0 % m) + m) % m : -1;\n}\n", "py": "def mod_inverse(a, m):\n    # Extended Euclid keeps a*x0 ≡ r0 (mod m) as r shrinks to gcd(a, m).\n    r0, r1, x0, x1 = a % m, m, 1, 0\n    while r1:\n        q = r0 // r1\n        r0, r1 = r1, r0 - q * r1\n        x0, x1 = x1, x0 - q * x1\n    return x0 % m if r0 == 1 else -1\n"}, "tests": [{"args": [3, 11], "expected": 4}, {"args": [10, 17], "expected": 12}, {"args": [6, 9], "expected": -1}, {"args": [1, 2], "expected": 1}, {"args": [2, 1000000007], "expected": 500000004}, {"args": [123456789, 1000000007], "expected": 18633540}, {"args": [35, 77], "expected": -1}, {"args": [999999999, 1000000000], "expected": 999999999}], "hints": ["An inverse exists iff gcd(a, m) = 1.", "Extended Euclid finds x, y with a·x + m·y = gcd(a, m); then x mod m is the inverse. (If m is prime, a^(m−2) mod m also works.)"], "complexity": "O(log m) time"},
  {"id": "unique-bsts", "title": "Unique Binary Search Trees", "level": "Medium", "topic": "combinatorics", "pattern": "Catalan numbers", "statement": "Return how many structurally unique BSTs store exactly the values 1..n.", "examples": [{"input": "n = 3", "output": "5"}, {"input": "n = 1", "output": "1"}], "fn": {"js": "numTrees", "py": "num_trees"}, "starter": {"js": "function numTrees(n) {\n  // your code here\n}\n", "py": "def num_trees(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function numTrees(n) {\n  // Closed form: C(n) = C(2n, n) / (n + 1), computed incrementally.\n  let c = 1;\n  for (let k = 0; k < n; k++) c = (c * 2 * (2 * k + 1)) / (k + 2);\n  return Math.round(c);\n}\n", "py": "def num_trees(n):\n    c = [1] + [0] * n                  # c[k] = Catalan(k)\n    for k in range(1, n + 1):\n        for root in range(1, k + 1):   # root splits into (root-1) left and (k-root) right\n            c[k] += c[root - 1] * c[k - root]\n    return c[n]\n"}, "tests": [{"args": [3], "expected": 5}, {"args": [1], "expected": 1}, {"args": [0], "expected": 1}, {"args": [2], "expected": 2}, {"args": [4], "expected": 14}, {"args": [10], "expected": 16796}, {"args": [19], "expected": 1767263190}], "hints": ["Pick the root r: the left subtree has r − 1 values, the right has n − r.", "count(n) = Σ count(r − 1) · count(n − r): the Catalan recurrence."], "complexity": "O(n²) DP (O(n) closed form)"},
  {"id": "kth-permutation", "title": "Permutation Sequence", "level": "Hard", "topic": "combinatorics", "pattern": "Factorial number system", "statement": "The permutations of 1..n listed in lexicographic order are numbered from 1. Return the k-th as a string (1 ≤ n ≤ 9).", "examples": [{"input": "n = 3, k = 3", "output": "\"213\""}, {"input": "n = 4, k = 9", "output": "\"2314\""}, {"input": "n = 3, k = 1", "output": "\"123\""}], "fn": {"js": "getPermutation", "py": "get_permutation"}, "starter": {"js": "function getPermutation(n, k) {\n  // your code here\n}\n", "py": "def get_permutation(n, k):\n    # your code here\n    pass\n"}, "solution": {"js": "function getPermutation(n, k) {\n  const digits = Array.from({ length: n }, (_, i) => String(i + 1));\n  const fact = [1];\n  for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;\n  k--;\n  let out = \"\";\n  for (let i = n; i >= 1; i--) {\n    const idx = Math.floor(k / fact[i - 1]);\n    k %= fact[i - 1];\n    out += digits.splice(idx, 1)[0];\n  }\n  return out;\n}\n", "py": "from math import factorial\n\ndef get_permutation(n, k):\n    digits = [str(i) for i in range(1, n + 1)]\n    k -= 1                               # 0-indexed\n    out = []\n    for i in range(n, 0, -1):\n        block = factorial(i - 1)          # permutations per choice of the next digit\n        idx, k = divmod(k, block)\n        out.append(digits.pop(idx))\n    return \"\".join(out)\n"}, "tests": [{"args": [3, 3], "expected": "213"}, {"args": [4, 9], "expected": "2314"}, {"args": [3, 1], "expected": "123"}, {"args": [1, 1], "expected": "1"}, {"args": [3, 6], "expected": "321"}, {"args": [9, 362880], "expected": "987654321"}, {"args": [9, 100000], "expected": "358926471"}], "hints": ["Generating permutations one by one is O(k · n).", "With n digits, each choice of the first digit covers (n − 1)! permutations: divide k by (n − 1)! to pick it, then recurse."], "complexity": "O(n²) time"},
  {"id": "count-sorted-vowel-strings", "title": "Count Sorted Vowel Strings", "level": "Medium", "topic": "combinatorics", "pattern": "Stars and bars", "statement": "Return the number of strings of length `n` made of vowels (a, e, i, o, u) that are sorted (each character ≤ the next).", "examples": [{"input": "n = 1", "output": "5"}, {"input": "n = 2", "output": "15"}, {"input": "n = 33", "output": "66045"}], "fn": {"js": "countVowelStrings", "py": "count_vowel_strings"}, "starter": {"js": "function countVowelStrings(n) {\n  // your code here\n}\n", "py": "def count_vowel_strings(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function countVowelStrings(n) {\n  // DP: dp[v] = number of sorted strings ending with a vowel ≤ v.\n  const dp = [1, 1, 1, 1, 1];\n  for (let len = 2; len <= n; len++) for (let v = 1; v < 5; v++) dp[v] += dp[v - 1];\n  return dp.reduce((a, b) => a + b, 0);\n}\n", "py": "from math import comb\n\ndef count_vowel_strings(n):\n    # Choose how many of each vowel: x_a + x_e + x_i + x_o + x_u = n  →  C(n + 4, 4)\n    return comb(n + 4, 4)\n"}, "tests": [{"args": [1], "expected": 5}, {"args": [2], "expected": 15}, {"args": [33], "expected": 66045}, {"args": [3], "expected": 35}, {"args": [10], "expected": 1001}, {"args": [50], "expected": 316251}], "hints": ["A sorted string is decided by how many of each vowel it has.", "Counting non-negative solutions of x₁ + … + x₅ = n is stars and bars: C(n + 4, 4)."], "complexity": "O(1) with the formula"},
  {"id": "knight-probability", "title": "Knight Probability in Chessboard", "level": "Medium", "topic": "probability", "pattern": "DP over probability distributions", "statement": "A knight starts at (row, column) on an n × n board and makes `k` uniformly random moves (it may leave the board, after which it stops). Return the probability it is still on the board after k moves.", "examples": [{"input": "n = 3, k = 2, row = 0, column = 0", "output": "0.0625"}, {"input": "n = 1, k = 0, row = 0, column = 0", "output": "1.0"}], "fn": {"js": "knightProbability", "py": "knight_probability"}, "starter": {"js": "function knightProbability(n, k, row, column) {\n  // your code here\n}\n", "py": "def knight_probability(n, k, row, column):\n    # your code here\n    pass\n"}, "solution": {"js": "function knightProbability(n, k, row, column) {\n  const moves = [[1, 2], [2, 1], [-1, 2], [-2, 1], [1, -2], [2, -1], [-1, -2], [-2, -1]];\n  let dp = Array.from({ length: n }, () => new Array(n).fill(0));\n  dp[row][column] = 1;\n  for (let s = 0; s < k; s++) {\n    const next = Array.from({ length: n }, () => new Array(n).fill(0));\n    for (let r = 0; r < n; r++)\n      for (let c = 0; c < n; c++)\n        if (dp[r][c])\n          for (const [dr, dc] of moves) {\n            const nr = r + dr, nc = c + dc;\n            if (nr >= 0 && nc >= 0 && nr < n && nc < n) next[nr][nc] += dp[r][c] / 8;\n          }\n    dp = next;\n  }\n  return dp.flat().reduce((a, b) => a + b, 0);\n}\n", "py": "def knight_probability(n, k, row, column):\n    moves = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]\n    dp = [[0.0] * n for _ in range(n)]\n    dp[row][column] = 1.0                 # probability mass on each square\n    for _ in range(k):\n        nxt = [[0.0] * n for _ in range(n)]\n        for r in range(n):\n            for c in range(n):\n                if dp[r][c]:\n                    for dr, dc in moves:\n                        nr, nc = r + dr, c + dc\n                        if 0 <= nr < n and 0 <= nc < n:\n                            nxt[nr][nc] += dp[r][c] / 8\n        dp = nxt\n    return sum(map(sum, dp))\n"}, "tests": [{"args": [3, 2, 0, 0], "expected": 0.0625}, {"args": [1, 0, 0, 0], "expected": 1.0}, {"args": [8, 30, 6, 4], "expected": 0.0001905256629833365}, {"args": [3, 1, 1, 1], "expected": 0.0}, {"args": [5, 3, 2, 2], "expected": 0.25}], "compare": "float", "hints": ["Simulating random walks only estimates the answer.", "Track the probability of being on each square after each move: each square sends 1/8 of its mass to each knight move."], "complexity": "O(k · n²) time, O(n²) space"},
  {"id": "new-21-game", "title": "New 21 Game", "level": "Medium", "topic": "probability", "pattern": "Sliding-window sum of probabilities", "statement": "Start at 0 points. While you have fewer than `k` points, draw a uniform random integer in [1, maxPts] and add it. Return the probability that you finish with at most `n` points.", "examples": [{"input": "n = 10, k = 1, max_pts = 10", "output": "1.0"}, {"input": "n = 6, k = 1, max_pts = 10", "output": "0.6"}, {"input": "n = 21, k = 17, max_pts = 10", "output": "0.73278"}], "fn": {"js": "new21Game", "py": "new21_game"}, "starter": {"js": "function new21Game(n, k, maxPts) {\n  // your code here\n}\n", "py": "def new21_game(n, k, max_pts):\n    # your code here\n    pass\n"}, "solution": {"js": "function new21Game(n, k, maxPts) {\n  if (k === 0 || n >= k - 1 + maxPts) return 1;\n  const dp = new Array(n + 1).fill(0);\n  dp[0] = 1;\n  let window = 1, ans = 0;\n  for (let x = 1; x <= n; x++) {\n    dp[x] = window / maxPts;\n    if (x < k) window += dp[x]; else ans += dp[x];\n    if (x - maxPts >= 0 && x - maxPts < k) window -= dp[x - maxPts];\n  }\n  return ans;\n}\n", "py": "def new21_game(n, k, max_pts):\n    if k == 0 or n >= k - 1 + max_pts:\n        return 1.0\n    dp = [0.0] * (n + 1)          # dp[x] = probability of ever having exactly x points\n    dp[0] = 1.0\n    window = 1.0                  # sum of dp over the last max_pts reachable-to-draw states\n    for x in range(1, n + 1):\n        dp[x] = window / max_pts\n        if x < k:\n            window += dp[x]       # we keep drawing from x\n        if x - max_pts >= 0 and x - max_pts < k:\n            window -= dp[x - max_pts]\n    return sum(dp[k:])\n"}, "tests": [{"args": [10, 1, 10], "expected": 1.0}, {"args": [6, 1, 10], "expected": 0.6000000000000001}, {"args": [21, 17, 10], "expected": 0.7327777870686081}, {"args": [0, 0, 1], "expected": 1.0}, {"args": [5, 3, 3], "expected": 1.0}, {"args": [100, 50, 20], "expected": 1.0}], "compare": "float", "hints": ["dp[x] = (dp[x−1] + … + dp[x−maxPts]) / maxPts, counting only states x − j < k (where you still draw).", "Keep that sum as a sliding window to make it O(n)."], "complexity": "O(n) time and space"},
  {"id": "fibonacci-mod-huge", "title": "Fibonacci for Huge n", "level": "Medium", "topic": "matrix-exponentiation", "pattern": "2×2 matrix power", "statement": "Return F(n) mod 10⁹ + 7, where F(0) = 0, F(1) = 1, and n can be as large as 10¹⁵.", "examples": [{"input": "n = 10", "output": "55"}, {"input": "n = 0", "output": "0"}, {"input": "n = 1", "output": "1"}], "fn": {"js": "fibMod", "py": "fib_mod"}, "starter": {"js": "function fibMod(n) {\n  // your code here\n}\n", "py": "def fib_mod(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function fibMod(n) {\n  // Fast doubling: F(2k) = F(k)·(2F(k+1) − F(k)), F(2k+1) = F(k)² + F(k+1)².\n  const MOD = 1000000007n;\n  const go = (k) => {\n    if (k === 0n) return [0n, 1n];\n    const [a, b] = go(k >> 1n);\n    const c = (a * ((2n * b - a + MOD) % MOD)) % MOD, d = (a * a + b * b) % MOD;\n    return k & 1n ? [d, (c + d) % MOD] : [c, d];\n  };\n  return Number(go(BigInt(n))[0]);\n}\n", "py": "def fib_mod(n):\n    MOD = 10**9 + 7\n    def mul(A, B):\n        return [[(A[0][0] * B[0][0] + A[0][1] * B[1][0]) % MOD, (A[0][0] * B[0][1] + A[0][1] * B[1][1]) % MOD],\n                [(A[1][0] * B[0][0] + A[1][1] * B[1][0]) % MOD, (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % MOD]]\n    result, base = [[1, 0], [0, 1]], [[1, 1], [1, 0]]   # [[F(n+1), F(n)], [F(n), F(n-1)]] = base^n\n    while n:\n        if n & 1:\n            result = mul(result, base)\n        base = mul(base, base)\n        n >>= 1\n    return result[0][1]\n"}, "tests": [{"args": [10], "expected": 55}, {"args": [0], "expected": 0}, {"args": [1], "expected": 1}, {"args": [2], "expected": 1}, {"args": [50], "expected": 586268941}, {"args": [100], "expected": 687995182}, {"args": [1000000000000000], "expected": 648325137}, {"args": [123456789012345], "expected": 875118832}], "hints": ["The recurrence is linear: (F(n+1), F(n)) = M · (F(n), F(n−1)) with M = [[1,1],[1,0]].", "So F(n) comes from Mⁿ, computed with O(log n) matrix squarings."], "complexity": "O(log n) time"},
  {"id": "max-points-on-a-line", "title": "Max Points on a Line", "level": "Hard", "topic": "geometry", "pattern": "Normalized slope hashing", "statement": "Given distinct integer `points`, return the maximum number of them that lie on one straight line.", "examples": [{"input": "points = [[1,1],[2,2],[3,3]]", "output": "3"}, {"input": "points = [[1,1],[3,2],[5,3],[4,1],[2,3],[1,4]]", "output": "4"}], "fn": {"js": "maxPoints", "py": "max_points"}, "starter": {"js": "function maxPoints(points) {\n  // your code here\n}\n", "py": "def max_points(points):\n    # your code here\n    pass\n"}, "solution": {"js": "function maxPoints(points) {\n  if (points.length <= 2) return points.length;\n  // O(n³) with cross products: no slopes or hashing needed.\n  let best = 2;\n  for (let i = 0; i < points.length; i++)\n    for (let j = i + 1; j < points.length; j++) {\n      const [x1, y1] = points[i], [x2, y2] = points[j];\n      let count = 2;\n      for (let k = j + 1; k < points.length; k++) {\n        const [x3, y3] = points[k];\n        if ((x2 - x1) * (y3 - y1) === (y2 - y1) * (x3 - x1)) count++;\n      }\n      best = Math.max(best, count);\n    }\n  return best;\n}\n", "py": "from math import gcd\nfrom collections import Counter\n\ndef max_points(points):\n    best = 1 if points else 0\n    for i, (x1, y1) in enumerate(points):\n        slopes = Counter()\n        for x2, y2 in points[i + 1:]:\n            dx, dy = x2 - x1, y2 - y1\n            g = gcd(dx, dy)\n            dx, dy = dx // g, dy // g\n            if dx < 0 or (dx == 0 and dy < 0):     # one canonical sign per direction\n                dx, dy = -dx, -dy\n            slopes[(dx, dy)] += 1                  # exact fraction, no floating point\n        if slopes:\n            best = max(best, 1 + max(slopes.values()))\n    return best\n"}, "tests": [{"args": [[[1, 1], [2, 2], [3, 3]]], "expected": 3}, {"args": [[[1, 1], [3, 2], [5, 3], [4, 1], [2, 3], [1, 4]]], "expected": 4}, {"args": [[[0, 0]]], "expected": 1}, {"args": [[[0, 0], [1, 1]]], "expected": 2}, {"args": [[[0, 0], [0, 1], [0, 2], [1, 0], [2, 0], [3, 0]]], "expected": 4}, {"args": [[[-6, -1], [3, 1], [12, 3]]], "expected": 3}], "hints": ["Fix one point; every other point defines a direction. Points on the same line share a direction.", "Store directions as reduced fractions (dx/g, dy/g) with a canonical sign to avoid floating-point errors."], "complexity": "O(n²) time with hashing"},
  {"id": "rectangle-overlap", "title": "Rectangle Overlap", "level": "Easy", "topic": "geometry", "pattern": "Overlap on both axes", "statement": "Axis-aligned rectangles are given as [x1, y1, x2, y2] (bottom-left, top-right). Return `true` if they overlap with positive area (touching edges or corners don't count).", "examples": [{"input": "rec1 = [0,0,2,2], rec2 = [1,1,3,3]", "output": "true"}, {"input": "rec1 = [0,0,1,1], rec2 = [1,0,2,1]", "output": "false"}, {"input": "rec1 = [0,0,1,1], rec2 = [2,2,3,3]", "output": "false"}], "fn": {"js": "isRectangleOverlap", "py": "is_rectangle_overlap"}, "starter": {"js": "function isRectangleOverlap(rec1, rec2) {\n  // your code here\n}\n", "py": "def is_rectangle_overlap(rec1, rec2):\n    # your code here\n    pass\n"}, "solution": {"js": "function isRectangleOverlap(rec1, rec2) {\n  return Math.min(rec1[2], rec2[2]) > Math.max(rec1[0], rec2[0]) && Math.min(rec1[3], rec2[3]) > Math.max(rec1[1], rec2[1]);\n}\n", "py": "def is_rectangle_overlap(rec1, rec2):\n    # Two intervals overlap iff each starts before the other ends.\n    return (min(rec1[2], rec2[2]) > max(rec1[0], rec2[0]) and\n            min(rec1[3], rec2[3]) > max(rec1[1], rec2[1]))\n"}, "tests": [{"args": [[0, 0, 2, 2], [1, 1, 3, 3]], "expected": true}, {"args": [[0, 0, 1, 1], [1, 0, 2, 1]], "expected": false}, {"args": [[0, 0, 1, 1], [2, 2, 3, 3]], "expected": false}, {"args": [[0, 0, 10, 10], [2, 2, 3, 3]], "expected": true}, {"args": [[-5, -5, 0, 0], [-1, -1, 4, 4]], "expected": true}, {"args": [[0, 0, 2, 2], [2, 2, 4, 4]], "expected": false}], "hints": ["Rectangles overlap iff their x-intervals overlap AND their y-intervals overlap.", "Intervals [a, b] and [c, d] overlap with positive length iff min(b, d) > max(a, c)."], "complexity": "O(1) time"},
  {"id": "nim-game", "title": "Nim Game", "level": "Easy", "topic": "game-theory", "pattern": "Losing positions are multiples of 4", "statement": "There is one pile of `n` stones. Players alternate removing 1, 2 or 3 stones; whoever removes the last stone wins. You go first and both play optimally. Can you win?", "examples": [{"input": "n = 4", "output": "false"}, {"input": "n = 1", "output": "true"}, {"input": "n = 2", "output": "true"}], "fn": {"js": "canWinNim", "py": "can_win_nim"}, "starter": {"js": "function canWinNim(n) {\n  // your code here\n}\n", "py": "def can_win_nim(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function canWinNim(n) {\n  // DP check of the pattern (for small n): win[i] = some move leads to a losing position.\n  if (n > 1000) return n % 4 !== 0;\n  const win = [false];\n  for (let i = 1; i <= n; i++) win[i] = [1, 2, 3].some((t) => i - t >= 0 && !win[i - t]);\n  return win[n];\n}\n", "py": "def can_win_nim(n):\n    # Positions 0, 4, 8, ... are losing: whatever you take (1-3), the opponent restores a multiple of 4.\n    return n % 4 != 0\n"}, "tests": [{"args": [4], "expected": false}, {"args": [1], "expected": true}, {"args": [2], "expected": true}, {"args": [5], "expected": true}, {"args": [8], "expected": false}, {"args": [1348820612], "expected": false}, {"args": [7], "expected": true}], "hints": ["Work out small cases: who wins with 1, 2, 3, 4, 5 stones?", "A position is losing if every move leads to a winning position. The losing ones are exactly the multiples of 4."], "complexity": "O(1) time"},
  {"id": "can-i-win", "title": "Can I Win", "level": "Medium", "topic": "game-theory", "pattern": "Minimax with bitmask memo", "statement": "Players alternately pick an unused integer from 1..`maxChoosableInteger` and add it to a running total. Whoever makes the total reach at least `desiredTotal` wins. Return whether the first player can force a win.", "examples": [{"input": "max_choosable_integer = 10, desired_total = 11", "output": "false"}, {"input": "max_choosable_integer = 10, desired_total = 0", "output": "true"}, {"input": "max_choosable_integer = 10, desired_total = 1", "output": "true"}], "fn": {"js": "canIWin", "py": "can_i_win"}, "starter": {"js": "function canIWin(maxChoosableInteger, desiredTotal) {\n  // your code here\n}\n", "py": "def can_i_win(max_choosable_integer, desired_total):\n    # your code here\n    pass\n"}, "solution": {"js": "function canIWin(maxChoosableInteger, desiredTotal) {\n  const M = maxChoosableInteger;\n  if (desiredTotal <= 0) return true;\n  if ((M * (M + 1)) / 2 < desiredTotal) return false;\n  const memo = new Map();\n  const wins = (used, remaining) => {\n    if (memo.has(used)) return memo.get(used);   // remaining is determined by used\n    let res = false;\n    for (let x = 1; x <= M && !res; x++) {\n      const bit = 1 << x;\n      if (!(used & bit) && (x >= remaining || !wins(used | bit, remaining - x))) res = true;\n    }\n    memo.set(used, res);\n    return res;\n  };\n  return wins(0, desiredTotal);\n}\n", "py": "from functools import lru_cache\n\ndef can_i_win(max_choosable_integer, desired_total):\n    M, T = max_choosable_integer, desired_total\n    if T <= 0:\n        return True\n    if M * (M + 1) // 2 < T:\n        return False                     # even using every number never reaches T\n    @lru_cache(None)\n    def wins(used, remaining):           # does the player to move win?\n        for x in range(1, M + 1):\n            bit = 1 << x\n            if not used & bit:\n                if x >= remaining or not wins(used | bit, remaining - x):\n                    return True\n        return False\n    return wins(0, T)\n"}, "tests": [{"args": [10, 11], "expected": false}, {"args": [10, 0], "expected": true}, {"args": [10, 1], "expected": true}, {"args": [5, 50], "expected": false}, {"args": [4, 6], "expected": true}, {"args": [10, 40], "expected": false}, {"args": [12, 49], "expected": true}], "hints": ["You win if some move either reaches the target or leaves the opponent in a losing state.", "The state is just the set of used numbers (the total follows from it): memoize on a bitmask."], "complexity": "O(2^M · M) time"},
  {"id": "chinese-remainder", "title": "Chinese Remainder Theorem", "level": "Medium", "topic": "advanced-number-theory", "pattern": "Combine congruences one at a time", "statement": "Given `remainders` rᵢ and pairwise coprime `moduli` mᵢ, return the smallest non-negative x with x ≡ rᵢ (mod mᵢ) for all i. The product of the moduli is below 10¹⁵.", "examples": [{"input": "remainders = [2,3,2], moduli = [3,5,7]", "output": "23", "explain": "The classic puzzle from Sunzi Suanjing."}, {"input": "remainders = [1], moduli = [2]", "output": "1"}], "fn": {"js": "crt", "py": "crt"}, "starter": {"js": "function crt(remainders, moduli) {\n  // your code here\n}\n", "py": "def crt(remainders, moduli):\n    # your code here\n    pass\n"}, "solution": {"js": "function crt(remainders, moduli) {\n  // BigInt: intermediate products exceed 2^53.\n  const inv = (a, m) => { let [r0, r1, x0, x1] = [((a % m) + m) % m, m, 1n, 0n]; while (r1) { const q = r0 / r1; [r0, r1] = [r1, r0 - q * r1]; [x0, x1] = [x1, x0 - q * x1]; } return ((x0 % m) + m) % m; };\n  let x = 0n, M = 1n;\n  for (let i = 0; i < moduli.length; i++) {\n    const r = BigInt(remainders[i]), m = BigInt(moduli[i]);\n    const t = ((((r - x) % m) + m) % m * inv(M % m, m)) % m;\n    x += M * t;\n    M *= m;\n  }\n  return Number(((x % M) + M) % M);\n}\n", "py": "def crt(remainders, moduli):\n    x, M = 0, 1                          # invariant: x satisfies the congruences seen so far, mod M\n    for r, m in zip(remainders, moduli):\n        # need x + M*t ≡ r (mod m)  →  t ≡ (r - x) * M^{-1} (mod m)\n        t = (r - x) * pow(M, -1, m) % m\n        x += M * t\n        M *= m\n    return x % M\n"}, "tests": [{"args": [[2, 3, 2], [3, 5, 7]], "expected": 23}, {"args": [[1], [2]], "expected": 1}, {"args": [[0, 0], [4, 9]], "expected": 0}, {"args": [[1, 2, 3, 4], [5, 7, 9, 11]], "expected": 1731}, {"args": [[999, 12345, 7], [1000, 99991, 11]], "expected": 759343999}, {"args": [[3, 4], [7, 13]], "expected": 17}], "hints": ["Merge the congruences one by one. If x works mod M, the new solution is x + M·t for some t.", "Solve for t with the inverse of M mod m (it exists because the moduli are coprime)."], "complexity": "O(k log max m) time"},
  {"id": "euler-totient", "title": "Euler's Totient Function", "level": "Easy", "topic": "advanced-number-theory", "pattern": "Product over prime factors", "statement": "Return φ(n): how many integers in [1, n] are coprime with n (1 ≤ n ≤ 10¹²).", "examples": [{"input": "n = 9", "output": "6", "explain": "1, 2, 4, 5, 7, 8"}, {"input": "n = 1", "output": "1"}, {"input": "n = 13", "output": "12"}], "fn": {"js": "phi", "py": "phi"}, "starter": {"js": "function phi(n) {\n  // your code here\n}\n", "py": "def phi(n):\n    # your code here\n    pass\n"}, "solution": {"js": "function phi(n) {\n  let result = n;\n  for (let p = 2; p * p <= n; p++)\n    if (n % p === 0) {\n      while (n % p === 0) n /= p;\n      result -= result / p;\n    }\n  if (n > 1) result -= result / n;\n  return result;\n}\n", "py": "def phi(n):\n    result, p = n, 2\n    while p * p <= n:\n        if n % p == 0:\n            while n % p == 0:\n                n //= p\n            result -= result // p        # multiply by (1 - 1/p)\n        p += 1\n    if n > 1:\n        result -= result // n            # leftover prime factor\n    return result\n"}, "tests": [{"args": [9], "expected": 6}, {"args": [1], "expected": 1}, {"args": [13], "expected": 12}, {"args": [36], "expected": 12}, {"args": [1000000007], "expected": 1000000006}, {"args": [999999999989], "expected": 999999999988}, {"args": [720720], "expected": 138240}], "hints": ["φ(n) = n · Π (1 − 1/p) over the distinct primes p dividing n.", "Find those primes by trial division up to √n."], "complexity": "O(√n) time"},
];
